    defer {
      self.index += 1
    }
    // 'SyntaxCollection' always has non-nil children. We can thus force-unwrap the element at 'index'.
    return Syntax(arena: arena, dataRef: layoutBuffer[self.index]!).cast(Element.self)
  }
